import { useEffect, useRef, useState } from "react";
import { clamp, ease } from "./helpers";
import '../index.css'

const TIMELINE = [
  {
    year: "1999",
    desc: "The first online shopping platform gained traction.",
    title: "Medium",
    sub: "Courier services",
    tilt: -2.5,
  },
  {
    year: "2015",
    desc: "A social media platform introduced shoppable tags, where people could directly sell on the platform.",
    title: "Medium",
    sub: "Fleet operators",
    tilt: 1.8,
  },
  {
    year: "2017",
    desc: "E-commerce platforms offered same-day delivery services to compete on speed and reach. Premium members.",
    title: "Medium",
    sub: "Fleet operators + delivery drivers",
    tilt: -1.5,
  },
  {
    year: "2019",
    desc: "Food delivery platforms competed for speed promising delivery in 10–15 minutes from micro-fulfillment centers.",
    title: "Medium",
    sub: "Delivery Partners + Dark stores",
    tilt: 2.2,
  },
  {
    year: "2021",
    desc: "Quick commerce gained popularity for providing sub-15 minute delivery for premium products.",
    title: "Medium",
    sub: "Delivery Partners + Dark stores",
    tilt: -1.8,
  },
  {
    year: "2025",
    desc: "On-demand services (cleaning, cooking, etc) can be booked instantly.",
    title: "Medium",
    sub: "For everything instantly",
    tilt: 1.2,
  },
];

function TimelineCard({ item, entrance }) {
  return (
    <div style={{
      opacity: entrance,
      transform: `translateX(${(1 - entrance) * 80}px) rotate(${item.tilt}deg)`,
      transformOrigin: "50% 0%",
      willChange: "transform, opacity",
      flexShrink: 0,
    }}>
      <div style={{
        width: 280,
        background: "#fff",
        borderRadius: 20,
        border: "2px solid #D7D7D7",
        overflow: "hidden",
        boxShadow: "0 8px 32px rgba(0,0,0,0.10), 0 2px 8px rgba(0,0,0,0.06)",
      }}>
        {/* Year + desc */}
        <div style={{ padding: "20px 20px 12px" }}>
          <div style={{
            display: "inline-block",
            color: "#CE1010",
            fontSize: 22, fontWeight: 800,
            fontFamily: "'Inter',sans-serif",
            letterSpacing: -0.5,
            marginBottom: 10,
          }}>{item.year}</div>
          <p style={{
            fontSize: 13, color: "#444", lineHeight: 1.65,
            fontFamily: "'Inter',sans-serif", margin: 0,
          }}>{item.desc}</p>
        </div>

        {/* Medium + sub */}
        <div style={{ padding: "10px 20px 14px" }}>
          <p style={{
            fontSize: 16, fontWeight: 800, color: "#1a1a1a",
            fontFamily: "'Inter',sans-serif",
            marginBottom: 2, letterSpacing: 0.1,
          }}>{item.title}</p>
          <p style={{
            fontSize: 12, color: "#888",
            fontFamily: "'Inter',sans-serif", lineHeight: 1.5, margin: 0,
          }}>{item.sub}</p>
        </div>

        {/* Image — tall, fills card bottom */}
        <div style={{
          margin: "0 12px 12px",
          borderRadius: 12,
          overflow: "hidden",
          height: 200,
          background: "#f5f5f5",
        }}>
          <img
            src="/assets/workforce.png"
            alt="workforce"
            style={{
              width: "100%", height: "100%",
              objectFit: "cover", display: "block",
            }}
          />
        </div>
      </div>
    </div>
  );
}

export default function TrustSection() {
  const sectionRef = useRef(null);
  const [p, setP] = useState(0);

  useEffect(() => {
    const onScroll = () => {
      const el = sectionRef.current;
      if (!el) return;
      const scrolled = -el.getBoundingClientRect().top;
      const total = el.offsetHeight - window.innerHeight;
      setP(Math.max(0, Math.min(1, scrolled / (total * 0.95))));
    };
    window.addEventListener("scroll", onScroll, { passive: true });
    onScroll();
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  const lp = (start, end) => ease(clamp((p - start) / (end - start), 0, 1));

  // ── Trust section scroll windows (0 → ~0.35 of total scroll) ──
  const TRUST_END = 0.35; // trust occupies first 35% of total scroll

  const ghost1 = lp(TRUST_END * 0.15, TRUST_END * 0.40);
  const ghost2 = lp(TRUST_END * 0.45, TRUST_END * 0.70);

  // ── Workforce section scroll windows (0.35 → 1.0 of total scroll) ──
  const WF_START = TRUST_END;

  const headerT = lp(WF_START, WF_START + 0.06);
  const railShift = ease(clamp((p - (WF_START + 0.05)) / 0.55, 0, 1));

  const cardEntrance = (i) => {
    const start = WF_START + 0.05 + i * 0.065;
    const end = start + 0.13;
    return ease(clamp((p - start) / (end - start), 0, 1));
  };

  // Crossfade: trust fades out, workforce fades in around TRUST_END
  const trustVisible = lp(0, TRUST_END * 0.85);
  const trustFadeOut = 1 - lp(TRUST_END * 0.70, TRUST_END * 0.95);
  const wfFadeIn = lp(TRUST_END * 0.80, TRUST_END + 0.04);

  return (
    // Total height = trust (280vh) + workforce (500vh) - 1 viewport overlap for seamless sticky handoff
    <div ref={sectionRef} style={{ height: "750vh", position: "relative" }}>

      {/* ══════════════════════════════════════════════
          TRUST SECTION — sticky panel 1
      ══════════════════════════════════════════════ */}
      <div
        id="dots-png"
        style={{
          position: "sticky",
          top: 0,
          height: "100vh",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          overflow: "hidden",
          padding: "0 6vw",
          opacity: trustFadeOut,
          // keep it in the stack but let workforce panel overlap when fading
          zIndex: trustFadeOut < 0.01 ? 0 : 2,
          pointerEvents: trustFadeOut < 0.01 ? "none" : "auto",
        }}
      >
        {/* ── Static big text ── */}
        <div style={{
          position: "relative",
          textAlign: "center",
          zIndex: 1,
          lineHeight: 1.08,
        }}>
          {/* Trust, */}
          <div>
            <span className="sm:text-[110px] text-[50px]" style={{
              fontFamily: "'Inter',sans-serif",
              fontWeight: 600, color: "#1A3BB0",
              display: "block", lineHeight: 1.0,
            }}>Trust,</span>
          </div>

          {/* however is fragile. */}
          <div style={{
            display: "flex", alignItems: "baseline",
            justifyContent: "center", gap: "0.2em", flexWrap: "wrap",
          }}>
            <span className="sm:text-[105px] text-[50px]" style={{
              fontFamily: "'Inter',sans-serif",
              fontWeight: 300, color: "#5D5D5D", lineHeight: 1.0,
            }}>however is  </span>
            <span className="sm:text-[105px] text-[50px]" style={{
              fontFamily: "'Inter',sans-serif",
              fontWeight: 700, color: "#343434", lineHeight: 1.05, marginLeft: "14px",
            }}>fragile.</span>
          </div>

          {/* One news headline. */}
          <div>
            <span className="sm:text-[105px] text-[50px]" style={{ fontFamily: "'Inter',sans-serif", fontWeight: 700, color: "#CE1010" }}>One </span>
            <span className="sm:text-[105px] text-[50px]" style={{ fontFamily: "'Inter',sans-serif", fontWeight: 400, color: "#5d5d5d" }}>news headline.</span>
          </div>

          {/* One breach */}
          <div>
            <span className="sm:text-[105px] text-[50px]" style={{ fontFamily: "'Inter',sans-serif", fontWeight: 700, color: "#CE1010" }}>One </span>
            <span className="sm:text-[105px] text-[50px]" style={{ fontFamily: "'Inter',sans-serif", fontWeight: 400, color: "#5d5d5d" }}>breach</span>
          </div>

          {/* One bad experience. */}
          <div>
            <span className="sm:text-[105px] text-[50px]" style={{ fontFamily: "'Inter',sans-serif", fontWeight: 700, color: "#CE1010" }}>One </span>
            <span className="sm:text-[105px] text-[50px]" style={{ fontFamily: "'Inter',sans-serif", fontWeight: 400, color: "#5d5d5d" }}>bad experience.</span>
          </div>

          {/* Footer line */}
          <div style={{ marginTop: 28 }}>
            <p style={{ fontSize: "20px", color: "#343434", lineHeight: 1.6, margin: 0 }}>
              is all it takes to undo years of hard-earned customer confidence.
            </p>
          </div>
        </div>

        {/* ── Ghost annotation 1 ── */}
        <div className="sm:left-[22%] left-[2%]" style={{
          position: "absolute",
          top: "42%",
          zIndex: 10,
          pointerEvents: "none",
          background: "rgba(243,242,242,0.55)",
          backdropFilter: "blur(12px)",
          WebkitBackdropFilter: "blur(12px)",
          borderRadius: 8,
          padding: "16px 22px",
          width: 390,
          opacity: ghost1,
          transform: `translateY(${(1 - ghost1) * 120}px)`,
          transition: "none",
        }}>
          <p style={{
            fontSize: 14, color: "#343434", lineHeight: 1.7,
            fontFamily: "'Inter',sans-serif", margin: 0,
          }}>
            When speed and scale take priority, due diligence
            slips and blind spots widen. That's exactly what is
            happening in the gig economy today.
          </p>
        </div>

        {/* ── Ghost annotation 2 ── */}
        <div style={{
          position: "absolute",
          right: "10%", bottom: "19%",
          zIndex: 10,
          pointerEvents: "none",
          background: "rgba(243,242,242,0.55)",
          backdropFilter: "blur(12px)",
          WebkitBackdropFilter: "blur(12px)",
          borderRadius: 8,
          padding: "16px 22px",
          width: 390,
          opacity: ghost2,
          transform: `translateY(${(1 - ghost2) * 120}px)`,
          transition: "none",
        }}>
          <p style={{
            fontSize: 14, color: "#343434", lineHeight: 1.7,
            fontFamily: "'Inter',sans-serif", margin: 0,
          }}>
            Identity swaps, impersonation, and hidden criminal
            histories do more than disrupt operations. They put
            safety, credibility, and customer trust at risk.
          </p>
        </div>
      </div>

      {/* ══════════════════════════════════════════════
          WORKFORCE SECTION — sticky panel 2
          Sits on top of trust panel once trust fades out
      ══════════════════════════════════════════════ */}
      <div style={{
        position: "sticky",
        top: 0,
        height: "135vh",
        overflow: "hidden",
        display: "flex",
        flexDirection: "column",
        background: "#fff",
        justifyContent: "center",
        opacity: wfFadeIn,
        zIndex: 3,
        pointerEvents: wfFadeIn < 0.05 ? "none" : "auto",
        // nudge it into view from below as trust fades
        transform: `translateY(${(1 - wfFadeIn) * 40}px)`,
      }}>

        {/* ── Header ── */}
        <div style={{
          padding: "0",
          textAlign: "center",
          opacity: headerT,
          transform: `translateY(${(1 - headerT) * 30}px)`,
          marginBottom: 52,
        }}>
          <h2 className="sm:text-[105px] text-[50px]" style={{
            fontFamily: "'Inter',sans-serif",
            fontWeight: 700, color: "#CE1010",
            lineHeight: 1.05, margin: "0 0 20px",
          }}>
            The Workforce<br />Behind Every Order
          </h2>
          <p style={{
            fontSize: "16px", color: "#343434",
            lineHeight: 1.75, maxWidth: 780,
            margin: "0 auto 10px",
          }}>
            India's doorstep economy operates at the intersection of logistics,
            technology, and human workforce. But that wasn't the case 15 years ago.
            Let's look at how the gig economy evolved with various business models
            over the last 3 decades.
          </p>
          <p style={{ fontSize: 13, color: "#aaa", fontStyle: "italic", margin: 0 }}>
            Sources:{" "}
            <span style={{ textDecoration: "underline", cursor: "pointer" }}>Kearney</span>{" "}
            <span style={{ textDecoration: "underline", cursor: "pointer" }}>Young Urban Project</span>{" "}
            <span style={{ textDecoration: "underline", cursor: "pointer" }}>Shiproket</span>
          </p>
        </div>

        {/* ── Cards rail ── */}
        <div style={{
          width: "100%",
          overflow: "visible",
          paddingLeft: "6vw",
        }}>
          <div style={{
            display: "flex",
            gap: 24,
            transform: `translateX(${(1 - railShift) * 55}vw)`,
            willChange: "transform",
            transition: "transform 0.15s cubic-bezier(0.25, 0.46, 0.45, 0.94)",
          }}>
            {TIMELINE.map((item, i) => (
              <TimelineCard
                key={item.year}
                item={item}
                entrance={cardEntrance(i)}
              />
            ))}
          </div>
        </div>

      </div>
    </div>
  );
}
